/* ============================================================
   "About this variant": a detailed description of every variant,
   in five parts: in one sentence; how the data are made (step by
   step, with the real numbers); what you will see; a real-world
   example; and why it matters in an interview.
   ABOUT.html(a, v, isBase, cur, open) -> HTML (a closed <details> by default)
   ============================================================ */
const ABOUT = (() => {
  const BASE1 = 'Draw x evenly between 0 and 10 (x = 10·u, sorted so the rows are in order, like time).';
  const ERR = 'Add an error ε = σ·z to every row, where z is a fresh draw from the bell curve and σ is the Noise slider.';
  const A = {

    /* ---------------- Feature engineering ---------------- */
    scnone: { one: 'Two features on very different scales are used as they are: x₁ runs from 0 to 10, x₂ from 1 000 to 5 000.', how: ['x₁ = 10·u₁.', 'x₂ = 1000 + 4000·u₂, and one row gets x₂ = 30 000 (it still sits on the true plane).', 'y = 2 + 1.5·x₁ + 0.002·x₂ + ε.', 'Step 5: no scaling, so the raw numbers go into X̃.'], see: 'The same predictions as with any scaling, but κ is enormous, and gradient descent (step 9b) barely moves in the allowed iterations.', real: 'Age in years next to income in rupees.', why: 'Least squares does not care about scale; gradient descent, ridge, lasso, PCA and distance-based models do.' },
    scstd: { one: 'Each feature becomes (x − mean) / sd, with the mean and sd of the training rows.', how: ['The same raw x₁, x₂ and y as in "None".', 'Step 5: compute the mean and sd of each feature on the training rows.', 'Replace every value (train and test) by (x − mean) / sd.'], see: 'Every feature has mean 0 and sd 1; κ is small; gradient descent converges quickly. Predictions are unchanged.', real: 'The default before gradient descent or regularisation.', why: 'Standardising gives the algebra balanced numbers without changing the model.' },
    scminmax: { one: 'Each feature is squeezed into [0, 1] with (x − min) / (max − min).', how: ['The same raw data.', 'Step 5: the training min and max of each feature.', 'x₂: the single value of 30 000 becomes the max, so the other x₂ values all land below about 0.15.'], see: 'A histogram of scaled x₂ crowded near 0 with one point at 1; predictions unchanged.', real: 'Neural-network inputs, image pixels.', why: 'Min–max scaling is defined by two extreme values, so one outlier ruins it.' },
    scrobust: { one: 'Each feature becomes (x − median) / IQR, which ignores extreme values.', how: ['The same raw data.', 'Step 5: the training median and the interquartile range (Q3 − Q1) of each feature.', 'The value 30 000 does not change the median or the IQR, so the other rows keep a normal spread.'], see: 'Scaled x₂ spread like a normal feature, with one far value; predictions unchanged.', real: 'Data with outliers.', why: 'Use robust scaling when extremes would distort the mean, sd, min or max.' },
    xtnone: { one: 'y rises with ln(x), but x is used as it is.', how: ['x = e^(0.9 + 0.7z): right-skewed, mostly small with a long tail of large values.', 'y = 2 + 3·ln(x) + ε.', 'Step 5: x goes in raw.'], see: 'The straight line in x is too high at both ends and too low in the middle; residuals bend; RESET rejects.', real: 'Sales against advertising spend.', why: 'The shape is wrong, so the predictions are biased by region.' },
    xtlog: { one: 'x is replaced by ln(x) in step 5.', how: ['The same raw x and y.', 'Step 5: z = ln(x) for every row.', 'The model is ŷ = b + w·ln(x).'], see: 'A straight relationship between y and ln x; drawn against the raw x the fit is a curve that follows the data. Residuals lose their bend.', real: 'Income, prices, populations.', why: 'With ln x, w/100 is the change in y for a 1% increase in x.' },
    xtsqrt: { one: 'x is replaced by √x.', how: ['The same raw data.', 'Step 5: z = √x.'], see: 'Less bend than raw x, more than ln x: a partial fix here.', real: 'Counts and areas.', why: 'The square root is a milder squeeze than the log.' },
    xtboxcox: { one: 'x is replaced by its Box-Cox transform, with the power λ chosen from the training rows.', how: ['The same raw data.', 'Step 5: try many λ; for each, transform the training x and compute the log-likelihood (−n/2·ln of the variance, plus (λ − 1)·Σ ln x).', 'Take the λ with the largest log-likelihood and transform every row with it.'], see: 'λ comes out near 0, so the result is close to the log.', real: 'Any positive, skewed feature.', why: 'Box-Cox picks the power automatically; λ is a parameter learned from the training rows.' },
    xtyj: { one: 'x is replaced by its Yeo-Johnson transform.', how: ['The same raw data.', 'Step 5: like Box-Cox, but with a formula that also works for zero and negative values; λ by maximum likelihood on the training rows.'], see: 'Similar to Box-Cox on this positive x.', real: 'Skewed features that can be negative (profits, changes).', why: 'Yeo-Johnson generalises Box-Cox to any real value.' },
    ytnone: { one: 'y grows exponentially with multiplicative noise and is modelled as it is.', how: ['x = 10·u.', 'y = e^(0.6 + 0.22x + 0.15·max(σ, 0.5)·z): every unit of x multiplies y by about 1.25, and the noise is a percentage.', 'Step 5: y goes in raw.'], see: 'A curve bending upward and fanning out; residuals curve, fan and skew.', real: 'Prices, incomes, file sizes.', why: 'One transform of y can fix linearity, spread and skew at once.' },
    ytlog: { one: 'The model is fitted to ln(y), and predictions are turned back with eˣ.', how: ['The same raw data.', 'Step 5: y′ = ln(y).', 'Fit y′ = b + w·x.', 'Step 12: ŷ = e^(ŷ′), scored against the original y.'], see: 'Straight, evenly spread residuals on the log scale; lower test error back in the units of y.', real: 'Sales, salaries, durations.', why: 'Each unit of x multiplies y by e^w. e^(ŷ′) estimates the median of y, not its mean.' },
    ytboxcox: { one: 'The model is fitted to the Box-Cox transform of y.', how: ['The same raw data.', 'Step 5: λ by maximum likelihood on the training y; y′ = (y^λ − 1)/λ.', 'Predictions turned back with (λŷ′ + 1)^(1/λ).'], see: 'λ near 0, so close to the log.', real: 'Positive targets of unknown skew.', why: 'Box-Cox chooses how strongly to compress y.' },
    deg1: { one: 'A straight line through an S-shaped truth.', how: ['x = 10·u.', 'y = 2 + 1.5x + 0.25(x − 5)² − 0.06(x − 5)³ + ε.', 'Step 5: only the column z (x standardised).'], see: 'The line misses both bends; residuals form a wave; train and test errors are both high (underfitting).', real: 'Any curved relationship modelled with a line.', why: 'Too simple a model has high bias.' },
    deg2: { one: 'A parabola: columns z and z² (z = standardised x).', how: ['The same raw data.', 'Step 5: z = (x − mean)/sd on the training rows, then z² (each row squared).'], see: 'Follows one bend but not the other.', real: '—', why: 'Each power adds one possible bend.' },
    deg3: { one: 'A cubic: columns z, z², z³ — the shape of the truth.', how: ['The same raw data.', 'Step 5: z = standardised x, then z² and z³.'], see: 'The fitted curve follows the truth; residuals are random; test error is the lowest of the degrees.', real: '—', why: 'The right flexibility balances bias and variance.' },
    deg5: { one: 'Degree 5: more flexible than needed.', how: ['The same raw data.', 'Step 5: z = standardised x, then z² … z⁵.'], see: 'Small extra wiggles; test error a little worse than degree 3.', real: '—', why: 'Extra columns add variance.' },
    deg10: { one: 'Degree 10: the curve chases the noise.', how: ['The same raw data.', 'Step 5: z = standardised x, then z² … z¹⁰ (standardising first matters: raw x¹⁰ would reach 10¹⁰).'], see: 'Wiggles between points and wild swings at the edges; low train error, higher test error; κ astronomically large.', real: 'A high-order polynomial on a small sample.', why: 'Overfitting: choose the degree by validation error, or use splines or ridge.' },
    intnone: { one: 'The effect of x₁ grows with x₂, but the model has no product term.', how: ['x₁ = 10·u₁, x₂ = 10·u₂.', 'y = 2 + 1.5x₁ + 1.0x₂ + 0.3·x₁·x₂ + ε.', 'Step 5: columns x₁ and x₂ only.'], see: 'A flat plane cannot follow the twist; residuals are positive where both are high or both low.', real: 'Advertising that works better in high season.', why: 'The model forces the slope of x₁ to be the same at every x₂.' },
    intx: { one: 'A product column x₁·x₂ is added.', how: ['The same raw data.', 'Step 5: x₁·x₂ for every row, then standardise.'], see: 'w₁₂ close to 0.3; residuals random; lower test error.', real: 'Dose × age effects in medicine.', why: 'The slope of x₁ becomes w₁ + w₁₂·x₂.' },
    spnone: { one: 'A straight line through a curve that rises fast and then levels off.', how: ['x = 10·u.', 'y = 2 + 8(1 − e^(−x/3)) + noise.', 'Step 5: column x only.'], see: 'Residuals form an upside-down U.', real: 'Learning curves, saturation.', why: 'A line cannot change slope.' },
    sp1: { one: 'A hinge at x = 5 lets the slope change there.', how: ['The same raw data.', 'Step 5: h₁ = max(0, x − 5): 0 below 5, x − 5 above.'], see: 'Two straight pieces joined at 5.', real: 'A threshold in a policy or a physical process.', why: 'The hinge weight is the change in slope at the knot.' },
    spmany: { one: 'Hinges at 2.5, 5 and 7.5.', how: ['The same raw data.', 'Step 5: three hinge columns, one per knot.'], see: 'Four pieces that follow the curve closely.', real: 'Smooth effects of age or temperature.', why: 'Splines bend locally and stay calm at the edges.' },
    binnone: { one: 'x bunched near 0 with a jump in y around x = 4, used as a number.', how: ['x = 10·u² (more small values).', 'y = 2 + 10/(1 + e^(−1.8(x − 4))) + noise.', 'Step 5: column x.'], see: 'A straight line cuts through the jump.', real: '—', why: 'The reference for binning.' },
    binwidth: { one: 'x cut into 5 bins of equal width.', how: ['The same raw data.', 'Step 5: edges at min + k·(max − min)/5 from the training rows.', 'One 0/1 column per bin except the first.'], see: 'A staircase fit; bins have very different counts because x is bunched.', real: 'Age groups.', why: 'Equal-width bins can be nearly empty.' },
    binquant: { one: 'x cut into 5 bins with the same number of training rows.', how: ['The same raw data.', 'Step 5: edges at the 20th, 40th, 60th and 80th percentiles of the training x.'], see: 'Even counts; narrower bins where x is dense.', real: 'Income quintiles.', why: 'Quantile bins keep every bin estimable.' },
    encoh: { one: 'region becomes three 0/1 columns, with East as the reference.', how: ['x = 10·u; region is recorded as text (East, North, South, West).', 'y = 2 + 1.5x + (0, 3, −2, 5 by region) + ε.', 'Step 5: region_North, region_South, region_West.'], see: 'One parallel line per region.', real: 'The standard encoding.', why: 'Each coefficient is the gap from East.' },
    encall: { one: 'All four region columns are kept next to the intercept.', how: ['The same raw data.', 'Step 5: four 0/1 columns.'], see: 'They add up to the intercept column: rank(X̃) < p, a zero eigenvalue, undefined SEs.', real: 'pd.get_dummies without drop_first.', why: 'The dummy-variable trap.' },
    encord: { one: 'region becomes one number: East 0, North 1, South 2, West 3.', how: ['The same raw data.', 'Step 5: code(region) = alphabetical position.'], see: 'One slope per code step; the true effects (0, 3, −2, 5) are not in that order, so the fit is poor.', real: 'Label-encoding an unordered category by mistake.', why: 'Integer codes invent an order and equal steps.' },
    enctarget: { one: 'region becomes one number: the mean y of its level in the training rows.', how: ['The same raw data.', 'Step 5: mean y per region on the training rows; each row gets the value of its region.'], see: 'One column; a fit close to one-hot.', real: 'High-cardinality categories.', why: 'Learn the means on training rows only (ideally out-of-fold), or it leaks.' },
    cenraw: { one: 'x lies between 20 and 30; the model uses x and x² as they are.', how: ['x = 20 + 10·u.', 'y = 2 + 1.5(x − 25) + 0.2(x − 25)² + ε.', 'Step 5: columns x and x², no scaling.'], see: 'x and x² correlate at about 0.999: huge VIF and κ, a large SE for x, and an intercept that describes x = 0, far outside the data.', real: 'Year (2000–2025) and year².', why: 'Powers of a variable far from 0 are almost collinear.' },
    cencent: { one: 'x is centred before squaring: xc = x − x̄.', how: ['The same raw data.', 'Step 5: x̄ from the training rows; columns xc and xc², no scaling.'], see: 'VIF near 1, a small SE for the linear term, and an intercept equal to the prediction at the average x. Predictions identical to "Raw".', real: 'Any model with powers or interactions.', why: 'Centring removes artificial collinearity.' },
    selall: { one: 'All 10 candidate columns are kept.', how: ['x₁ … x₄ = 10·u, independent.', 'x₅ = x₁ + 0.3z: almost a copy of x₁.', 'n₁ … n₅ = 10·u: noise.', 'y = 2 + 1.5x₁ + 1.0x₂ − 0.8x₃ + 0.5x₄ + ε.'], see: 'Noise columns get small, non-zero coefficients; x₁ and x₅ share the credit; test error a little above train.', real: 'A wide dataset before any pruning.', why: 'The reference for the selection methods.' },
    selfwd: { one: 'Columns are added one at a time by p-value.', how: ['The same 10 candidates.', 'Step 5: fit each single column; add the one with the smallest p-value if below 0.05; repeat with the rest.'], see: 'The path table in step 5 shows each addition.', real: 'Classic stepwise modelling.', why: 'Greedy, and the p-values afterwards ignore the search.' },
    selbwd: { one: 'Columns are removed one at a time by p-value.', how: ['The same 10 candidates.', 'Step 5: fit all; drop the column with the largest p-value if above 0.05; repeat.'], see: 'The path table in step 5 shows each removal.', real: 'Trimming a full model.', why: 'Same post-selection bias as forward.' },
    selstep: { one: 'Forward selection that re-checks earlier choices.', how: ['As forward, but after each addition any column whose p-value rose above 0.10 is removed.'], see: 'Usually the same as forward here.', real: 'Many statistics packages.', why: '—' },
    sellasso: { one: 'Lasso keeps the columns it does not shrink to 0.', how: ['The same 10 candidates.', 'Step 5: standardise; fit lasso for several λ; choose λ by 5-fold cross-validation inside the training rows; keep the non-zero columns.'], see: 'Noise columns at exactly 0 (the coordinate-descent update sets a weight to 0 when |ρ| ≤ λ).', real: 'High-dimensional data.', why: 'The L1 penalty selects and shrinks at once.' },
    selvif: { one: 'Columns with VIF above 5 are dropped one at a time.', how: ['The same 10 candidates.', 'Step 5: compute every VIF (regress each column on the others); drop the largest while above 5.'], see: 'x₁ or x₅ is dropped; the noise columns stay.', real: 'Removing redundant features.', why: 'VIF removes redundancy, not irrelevance.' },
    selp: { one: 'Fit once and drop every column with p > 0.05.', how: ['The same 10 candidates.', 'Step 5: one fit, one cut.'], see: 'x₁ and x₅ may both look insignificant because they share their information, and both get dropped.', real: 'Quick screening.', why: 'Correlated columns can hide each other’s significance.' },
    /* ---------------- Linearity ---------------- */
    linear: { one: 'The true relationship between x and y is a straight line, so a straight-line model has the right shape.', how: [BASE1, 'Compute the true mean of y: 2 + 1.5·x. Every extra unit of x adds exactly 1.5 to y, everywhere.', ERR, 'y = 2 + 1.5·x + ε.'], see: 'Points scatter evenly around one straight line. Residuals have no pattern along x, and RESET does not reject.', real: 'Cost of a taxi ride against distance, at a fixed price per km.', why: 'This is the baseline every other linearity variant is compared with: with the right shape, the least-squares line is unbiased.' },
    quadratic: { one: 'The truth curves upward (a U shape), but the model still draws a straight line.', how: [BASE1, 'True mean: 2 + 1.5·x + 0.3·s·(x − 5)². The extra term is 0 at x = 5 and grows on both sides, so the curve bends up at both ends.', ERR, 'Fit a straight line anyway.'], see: 'The line is too high in the middle and too low at both ends. Residuals form a U: positive, negative, positive along x. RESET rejects.', real: 'Fuel use against speed, cost against volume beyond capacity.', why: 'Non-linearity biases the predictions region by region. Fix it with a polynomial term (x²) or a transform, which is still linear regression because it is linear in the weights.' },
    log: { one: 'y rises quickly at first and then levels off (diminishing returns), but the model draws a straight line.', how: [BASE1, 'True mean: a blend (1 − s)·(2 + 1.5x) + s·(2 + 7·ln(1 + x)). At full strength the logarithm makes each extra unit of x add less than the one before.', ERR, 'Fit a straight line.'], see: 'An upside-down U in the residuals: the line is too high at both ends and too low in the middle.', real: 'Sales against advertising spend; learning curves.', why: 'A log transform of x (np.log1p(x)) turns this curve into a straight line.' },
    sshape: { one: 'y is flat, then rises steeply, then flattens again (an S-curve).', how: [BASE1, 'True mean: (1 − s)·(2 + 1.5x) + s·(2 + 15 / (1 + e^(−1.5(x − 5)))), a logistic curve centred at x = 5.', ERR, 'Fit a straight line.'], see: 'Residuals follow a wave: negative, positive, negative, positive along x.', real: 'Adoption of a new technology over time; dose–response curves.', why: 'One slope cannot describe three regimes. Splines or a logistic model fit the shape.' },
    step: { one: 'The mean of y jumps at a threshold, with almost no slope on either side.', how: [BASE1, 'True mean: (1 − s)·(2 + 1.5x) + s·(3 + 0.3x + 9·[x > 5]): a jump of 9 at x = 5.', ERR, 'Fit a straight line.'], see: 'The line cuts through the jump: residuals are negative just after 5 and positive just before it (or the other way round).', real: 'Price against age, where a policy changes at age 65.', why: 'A dummy for x > 5 (or a piecewise model) captures the jump; a straight line spreads it over the whole range.' },
    interaction: { one: 'Two customer types respond to x with different slopes, but the model gives them one shared slope.', how: [BASE1, 'Give each row a customer type at random: new or returning (about half each). It is recorded as text and encoded in step 5 as the 0/1 column customer_returning.', 'New customers: y = 2 + 1.5·x. Returning customers: y = 2 + 1.5·x + s·(1.4x − 7), so their slope is 1.5 + 1.4·s (2.9 at full strength).', ERR, 'Fit y ~ x + customer: two parallel lines, one shift, one common slope.'], see: 'Two parallel fitted lines, but the two clouds are not parallel: the lines are too steep for one type and too flat for the other.', real: 'The effect of a discount on new versus returning customers.', why: 'When the effect of x depends on a group, add the interaction x × group. Leaving it out is a form of non-linearity.' },
    periodic: { one: 'A straight trend plus a repeating wave.', how: [BASE1, 'True mean: 2 + 1.5·x + 4·s·sin(1.6x).', ERR, 'Fit a straight line.'], see: 'Residuals oscillate regularly along x, and neighbouring residuals have the same sign, so Durbin–Watson also reacts.', real: 'Monthly sales with seasonality; daily temperature.', why: 'Add sine and cosine terms (or seasonal dummies). A missed wave also shows up as autocorrelation.' },
    /* ---------------- Independence ---------------- */
    indep: { one: 'Every error is drawn fresh: no row knows anything about another row’s error.', how: [BASE1, 'True mean: 2 + 1.5·x.', ERR + ' Each z is independent of every other.'], see: 'Residuals change sign at random from one row to the next.', real: 'A survey of different, unrelated people.', why: 'Independence is what lets the standard error treat N rows as N pieces of information.' },
    posar: { one: 'Each error carries over part of the previous one, so neighbouring rows have similar errors (positive autocorrelation).', how: [BASE1 + ' The row order is time.', 'True mean: 2 + 1.5·x.', 'Errors: ε₁ = σ·z₁, then εₜ = ρ·εₜ₋₁ + √(1 − ρ²)·σ·zₜ with ρ = 0.9·s. Each error keeps 90% of the last one and adds a fresh shock; √(1 − ρ²) keeps the spread at σ.', 'y = 2 + 1.5·x + ε.'], see: 'Long runs of points on the same side of the line (the top chart colours them). Durbin–Watson well below 2; the lag plot tilts upward.', real: 'Monthly sales, stock prices, a slowly drifting sensor.', why: 'The slope stays unbiased, but classical SEs are too small because neighbours repeat information. Use Newey–West SEs or a time-series model, and split train/test by time.' },
    negar: { one: 'Each error tends to flip the sign of the previous one (negative autocorrelation).', how: [BASE1 + ' The row order is time.', 'Errors: εₜ = ρ·εₜ₋₁ + √(1 − ρ²)·σ·zₜ with ρ = −0.8·s.', 'y = 2 + 1.5·x + ε.'], see: 'Points zig-zag above and below the line almost every row. Durbin–Watson above 2.', real: 'Inventory that is over-ordered one week and under-ordered the next.', why: 'Classical SEs are now too large (too cautious). Newey–West fixes them.' },
    cluster: { one: 'Rows come in eight groups, and every row in a group shares a common shock.', how: ['Split the rows into 8 consecutive clusters.', 'x sits near a centre for each cluster (blended with uniform x by the strength).', 'Error: εᵢ = σ·(√q·u_cluster + √(1 − q)·zᵢ) with q = 0.8·s: part of the error is shared by the whole cluster.', 'y = 2 + 1.5·x + ε.'], see: 'Whole clusters sit above or below the line together; the residual strip by cluster shows shifted cluster means.', real: 'Students in the same class, patients in the same hospital.', why: 'N rows carry the information of far fewer independent ones, so classical SEs are far too small. Use clustered SEs and split by cluster.' },
    dupes: { one: 'Each real observation was recorded several times.', how: ['Draw ⌈N/k⌉ distinct rows with k = 1 + round(2s) (3 at full strength).', 'Write each one k times, with the same x, the same error and the same y.'], see: 'The scatter looks normal (copies sit on top of each other), but the duplicate check finds them and the residuals come in identical blocks.', real: 'A database join that duplicated rows; the same form submitted twice.', why: 'Copies add no information but shrink the SE by about √k. Remove duplicates before anything else.' },
    /* ---------------- Homoscedasticity ---------------- */
    constant: { one: 'The errors have the same spread everywhere.', how: [BASE1, 'True mean: 2 + 1.5·x.', ERR], see: 'A band of even width around the line. Breusch–Pagan does not reject.', real: 'A well-calibrated scale weighing similar objects.', why: 'Constant variance is what lets the classical SE use one number, s², for the noise.' },
    increasing: { one: 'The errors get bigger as x grows (a funnel).', how: [BASE1, 'True mean: 2 + 1.5·x.', 'Error: εᵢ = σ·[(1 − s) + s·(0.15 + 0.17·xᵢ)]·zᵢ: the multiplier goes from 0.15 at x = 0 to 1.85 at x = 10.'], see: 'The cloud fans out to the right; residuals vs x form a funnel; Breusch–Pagan rejects.', real: 'Spending against income: rich households vary more.', why: 'The slope is still unbiased, but classical SEs are wrong. Use HC (robust) SEs, weighted least squares, or a log transform of y.' },
    decreasing: { one: 'The errors get smaller as x grows.', how: [BASE1, 'Error multiplier 0.15 + 0.17·(10 − x): large at the left, small at the right.'], see: 'The funnel opens to the left.', real: 'Measurement error that shrinks as an instrument warms up.', why: 'Same fix as the increasing funnel: HC SEs or WLS.' },
    bowtie: { one: 'Small errors in the middle, large at both ends.', how: [BASE1, 'Error multiplier 0.2 + 0.32·|x − 5|.'], see: 'A bow-tie shape around the line. Breusch–Pagan on x may miss it, because the spread is symmetric in x.', real: 'Forecast errors that grow the further you are from the present.', why: 'Tests that look for a linear trend in the variance can miss symmetric patterns: always plot.' },
    groupvar: { one: 'Two groups with different error sizes.', how: [BASE1, 'Each row belongs to a group at random. Error multiplier 0.3 for one group and 1.7 for the other.'], see: 'Some points hug the line, others scatter widely; residuals by group differ.', real: 'Two machines, one precise and one noisy.', why: 'The variance depends on the group, not on x, so test e² against the group or plot residuals by group.' },
    /* ---------------- Normality ---------------- */
    normal: { one: 'The errors follow the bell curve.', how: [BASE1, 'True mean: 2 + 1.5·x.', ERR], see: 'Q–Q points on the diagonal; Jarque–Bera does not reject.', real: 'Many small independent influences adding up.', why: 'Normality is only needed for exact small-sample tests; with a few dozen rows the central limit theorem covers it.' },
    rskew: { one: 'Errors with a long right tail: mostly small, occasionally very large and positive.', how: [BASE1, 'Error: σ·[√(1 − s²)·z + s·(E − 1)], where E is exponential: never far below 0, sometimes far above.'], see: 'A few points far above the line; the residual histogram leans left with a long right tail; the Q–Q plot bows.', real: 'Delivery times: usually on time, sometimes very late.', why: 'Estimates stay unbiased; small-sample intervals can be off. A log transform of y often helps.' },
    lskew: { one: 'Errors with a long left tail.', how: [BASE1, 'Error: σ·[√(1 − s²)·z + s·(1 − E)].'], see: 'A few points far below the line.', real: 'Exam scores near a ceiling with occasional bad days.', why: 'Same as right skew, mirrored.' },
    heavy: { one: 'Heavy tails: extreme errors happen far more often than the bell curve allows.', how: [BASE1, 'Error: σ·[√(1 − s²)·z + s·t/√3], with t a Student-t with 3 degrees of freedom.'], see: 'A tall narrow peak with a few extreme residuals; the Q–Q plot forms an S.', real: 'Financial returns.', why: 'Extremes pull the least-squares line. Robust losses (Huber) down-weight them.' },
    light: { one: 'Light tails: errors never go far out (uniform).', how: [BASE1, 'Error: σ·[√(1 − s²)·z + s·√12·(U − ½)], U uniform.'], see: 'A flat-topped histogram; Jarque–Bera often passes.', real: 'Rounding errors.', why: 'Light tails are harmless for least squares and hard to detect.' },
    bimodal: { one: 'Errors with two humps.', how: [BASE1, 'Error: σ·[√(1 − s²)·z + s·(±0.95 + 0.31·z₂)]: each row is pushed up or down by about one σ.'], see: 'Two bands of points, above and below the line.', real: 'An unrecorded binary factor, such as two shifts of workers.', why: 'Two humps usually mean a missing group variable.' },
    /* ---------------- Multicollinearity ---------------- */
    uncorr: { one: 'Two features that are unrelated to each other.', how: ['x₁ = 10·u₁ and x₂ = 10·u₂, drawn independently.', 'y = 2 + 1.5·x₁ + 1.0·x₂ + ε.'], see: 'The x₁ vs x₂ scatter is a shapeless square; VIFs near 1.', real: 'Age and the day of the week of a purchase.', why: 'With unrelated features each coefficient is estimated as precisely as if it were alone.' },
    moderate: { one: 'Two features that move together moderately (r ≈ 0.6).', how: ['x₁ = 10·u₁.', 'x₂ = 5 + ρ(x₁ − 5) + √(1 − ρ²)(10u₂ − 5) with ρ = 0.6·s.', 'y = 2 + 1.5·x₁ + 1.0·x₂ + ε.'], see: 'A tilted cloud in x₁ vs x₂; VIF about 1.5; slightly larger SEs.', real: 'Age and income.', why: 'Moderate correlation is normal and harmless.' },
    high: { one: 'Two features that are almost the same (r ≈ 0.97).', how: ['x₁ = 10·u₁.', 'x₂ = 5 + ρ(x₁ − 5) + √(1 − ρ²)(10u₂ − 5) with ρ = 0.97·s.', 'y = 2 + 1.5·x₁ + 1.0·x₂ + ε.'], see: 'x₁ vs x₂ is nearly a line; VIF above 10; large κ; coefficients swing between samples (the Monte Carlo cloud in step 11 is a long thin ellipse).', real: 'House size in m² and number of rooms.', why: 'Predictions are fine, but the separate coefficients are unstable. Drop one, combine them, or use ridge.' },
    perfect: { one: 'One feature is an exact multiple of the other.', how: ['x₁ = 10·u₁.', 'x₂ = 2·x₁ + (1 − s)·2z: at full strength exactly 2·x₁.', 'y = 2 + 1.5·x₁ + 1.0·x₂ + ε.'], see: 'rank(X) < p, an eigenvalue of X̃ᵀX̃ is 0, κ is infinite and the SEs are undefined.', real: 'The same length recorded in cm and in inches.', why: 'There is no unique solution. Remove the copy.' },
    combo: { one: 'One feature is the exact sum of two others.', how: ['x₁ = 10·u₁, x₂ = 10·u₂.', 'x₃ = x₁ + x₂ + (1 − s)·1.5z.', 'y = 2 + 1.5x₁ + 1.0x₂ + 0.5x₃ + ε.'], see: 'No single pair looks perfectly correlated, yet rank(X) < p and VIF is infinite.', real: 'Total spend kept next to online spend and store spend.', why: 'Pairwise correlations miss combinations; VIF and the eigenvalues catch them.' },
    dummytrap: { one: 'A text column with three levels is encoded into three 0/1 columns and all three are kept next to the intercept.', how: ['x = 10·u.', 'Each row gets a colour at random: blue, green or red (recorded as text).', 'y = 2 + 1.5·x + (0, 3 or 6 for blue, green, red) + ε.', 'In step 5 the colour becomes colour_blue, colour_green and colour_red, and none is dropped.'], see: 'The raw data look fine. After encoding, the three columns add up to 1 on every row, which equals the intercept column: rank(X) < p.', real: 'One-hot encoding a categorical column and forgetting drop_first.', why: 'With an intercept, keep k − 1 dummies for k levels.' },
    /* ---------------- Exogeneity ---------------- */
    exo: { one: 'The error is unrelated to x, so the slope is the causal effect.', how: [BASE1, 'True mean: 2 + 1.5·x.', ERR + ' The errors are drawn independently of x.'], see: 'The fitted line sits on the true line.', real: 'A randomised experiment, where x is assigned by coin flip.', why: 'Exogeneity is what makes the slope mean "the effect of x".' },
    confounder: { one: 'A hidden variable pushes both x and y.', how: ['Draw a hidden z (bell curve).', 'x = 5 + 2s·z + 2.2·(noise): x rises with z.', 'y = 2 + 1.5·x + 3s·z + σ·ε: y also rises with z.', 'The model sees x and y, not z.'], see: 'The fitted line is steeper than the true slope 1.5, yet the residuals look perfectly healthy.', real: 'Ice-cream sales and drownings, both driven by temperature.', why: 'The slope is biased and more data does not help. Include the confounder or use an instrument.' },
    measerr: { one: 'x is measured with error.', how: ['True x = 10·u.', 'Recorded x = true x + 3s·z₂.', 'y = 2 + 1.5·(true x) + σ·ε, but the model uses the recorded x.'], see: 'The fitted line is flatter than the truth (attenuation).', real: 'Self-reported income; a noisy sensor.', why: 'Error in x biases the slope toward 0. Measure better, or use an errors-in-variables model.' },
    reverse: { one: 'y also pushes x.', how: ['Errors ε = σ·z.', 'x = 10·u + γ/(1 − 1.5γ)·ε with γ = 0.4s: a high error raises y, which raises x.', 'y = 2 + 1.5·x + ε.'], see: 'The slope is too steep; residuals look fine.', real: 'Police numbers and crime rates.', why: 'Needs an instrument or a structural model.' },
    /* ---------------- Outliers ---------------- */
    outnone: { one: 'Every row follows the same pattern.', how: [BASE1, 'True mean: 2 + 1.5·x.', ERR], see: 'No point stands apart; the largest Cook’s distance is small.', real: 'Clean, well-checked data.', why: 'The reference for the outlier variants.' },
    outy: { one: 'One row (about 1 in 60) has a far-too-large y at an ordinary x.', how: [BASE1, 'y = 2 + 1.5·x + ε for every row.', 'Pick a row near the middle of the x range and add 6·max(σ, 1)·s to its y.', 'That row is kept in the training set, so its effect is visible.'], see: 'One point far above the cloud. It lifts the line a little (mostly the intercept) and inflates s², so every SE grows. Its studentised residual is large, its leverage ordinary.', real: 'A typo with an extra digit; a one-off event.', why: 'An outlier in y at a typical x costs precision more than it moves the slope. Check it; use a robust loss if it is genuine.' },
    levon: { one: 'One row is far out in x but exactly on the trend.', how: [BASE1, 'y = 2 + 1.5·x + ε.', 'Move the last row to x = 10 + 15·s (25 at full strength) and give it the y the true line predicts there, plus its usual error.'], see: 'A point far to the right, on the line. Huge leverage, small residual, modest Cook’s distance, and the slope’s SE actually shrinks.', real: 'One very large house priced exactly as the trend says.', why: 'High leverage is not bad by itself: it is "good leverage" when the point agrees with the others.' },
    levoff: { one: 'One row is far out in x and far off the trend.', how: [BASE1, 'Move the last row to x = 10 + 15·s.', 'Give it a y that is 20·s below the true line.'], see: 'A point far to the right and far below the line. The fitted line tilts toward it; Cook’s distance is far above 1; dropping that one row moves the slope a lot (step 10, last sub-step).', real: 'A data-entry error in both columns.', why: 'Leverage plus a large residual means one row can decide the slope. Investigate it and report the fit with and without it.' },
    outcluster: { one: 'A small group of rows at high x is off the trend together.', how: [BASE1, 'Take about 1 row in 12 near the top of the x range.', 'Pull each of them down by 8·max(σ, 1)·s.'], see: 'A clump of points below the line at the right. The line bends toward them, but each row’s Cook’s distance can stay modest: removing one leaves the others holding the line (masking).', real: 'A batch measured with a faulty instrument.', why: 'One-at-a-time diagnostics can miss a group of outliers; look at the picture and refit without the whole group.' },
    /* ---------------- Sample size ---------------- */
    nlarge: { one: 'Plenty of rows: 200 rows for 5 features (6 coefficients).', how: ['N = 200 rows (the N slider is set by this variant).', 'x₁ = 10·u plus four extra independent features x₂…x₅ with coefficients 0.8, −0.6, 0.5, −0.4.', 'y = 2 + 1.5·x₁ + … + ε.'], see: 'Small SEs, train and test error close to σ.', real: 'A well-sized business dataset.', why: 'The reference for the other sample sizes.' },
    nmod: { one: 'A moderate number of rows: 60 for 5 features.', how: ['Same recipe as Large, with N = 60.'], see: 'SEs about √(200/60) ≈ 1.8 times larger than with 200 rows.', real: 'Most small studies.', why: 'SE shrinks like 1/√N.' },
    nsmall: { one: 'Few rows: 15 for 5 features, so 12 training rows and only 6 to spare.', how: ['Same recipe as Large, with N = 15.'], see: 'Wide intervals; a t critical value well above 2; test error clearly above training error (the learning curve in step 12).', real: 'A pilot study.', why: 'With few spare rows the model fits noise and the tests have little power.' },
    nap: { one: 'Only one more training row than coefficients (N ≈ p).', how: ['Choose N so that the training rows equal p + 1 (7 rows for 6 coefficients at 5 features).'], see: 'Training error near 0, test error large; one degree of freedom, so the 95% interval uses t = 12.7.', real: 'Many features measured on a handful of subjects.', why: 'N close to p means the model can fit almost anything. Drop features or regularise.' },
    nlp: { one: 'Fewer training rows than coefficients (N < p).', how: ['Choose N so that the training rows are p − 2 (4 rows for 6 coefficients at 5 features).'], see: 'Training error exactly 0; X̃ᵀX̃ has zero eigenvalues and no inverse; s², SEs and tests are reported as not available, with the reason.', real: 'Genomics: thousands of genes, dozens of patients.', why: 'Infinitely many weight vectors fit perfectly; least squares alone cannot choose (the app shows the shortest one). Ridge, lasso or PCA are needed.' },
    /* ---------------- Noise ---------------- */
    nslow: { one: 'The noise as set on the slider.', how: [BASE1, 'y = 2 + 1.5·x + σ·z with the slider’s σ.'], see: 'The usual scatter around the line.', real: '—', why: 'The reference for the noise variants.' },
    nszero: { one: 'No noise at all: σ = 0.', how: [BASE1, 'y = 2 + 1.5·x exactly.'], see: 'Every point on the line; R² = 1; every residual 0, so SEs are 0, t is infinite and the diagnostics report "not available".', real: 'Only exact formulas or simulations.', why: 'A perfect fit on real data usually means a formula or leakage, not a great model.' },
    nsmod: { one: 'Noticeably more noise: σ = 2.5 × max(slider σ, 1).', how: [BASE1, 'y = 2 + 1.5·x + 2.5·max(σ, 1)·z.'], see: 'A wider band around the same line; lower R²; larger SEs and test RMSE.', real: 'Survey data.', why: 'Noise lowers R² but does not bias the slope.' },
    nshigh: { one: 'Very large noise: σ = 6 × max(slider σ, 1).', how: [BASE1, 'y = 2 + 1.5·x + 6·max(σ, 1)·z.'], see: 'The line is hard to see by eye; R² near 0, yet the slope is still right on average.', real: 'Daily stock returns.', why: 'A low R² can come with a real, useful slope.' },
    nspure: { one: 'y has nothing to do with x: the true slope is 0.', how: [BASE1, 'y = 9.5 + ε, where ε has the same spread as the whole baseline y (√(1.5²·100/12 + σ²)).'], see: 'A shapeless cloud; R² near 0; the F-test does not reject; test R² near or below 0.', real: 'Testing an idea that is wrong.', why: 'Even with pure noise, about 5% of samples show a "significant" slope: that is what a 5% test means.' },
    /* ---------------- Range ---------------- */
    rwide: { one: 'x covers 0 to 10.', how: [BASE1, 'y = 2 + 1.5·x + ε.'], see: 'Points spread across the whole range.', real: '—', why: 'The reference for the range variants.' },
    rrestrict: { one: 'Only a narrow slice of x was observed.', how: ['Draw x as usual, then squeeze it toward 5: x = 5 + (x − 5)·(1 − 0.8s), so at full strength x lies between 4 and 6.', 'y = 2 + 1.5·x + ε.'], see: 'A narrow vertical band of points; the slope’s SE is much larger (SE = s / √Σ(x − x̄)²).', real: 'A study that recruited only middle-aged people.', why: 'The precision of a slope comes from the spread of x. Outside the observed range there is no evidence at all.' },
    rgap: { one: 'No rows between x = 4 and 7, and the truth has a bump hidden in that gap.', how: ['Move x values out of the middle: 0–5 is mapped to 0–4 and 5–10 to 7–10 (blended by the strength).', 'True mean: 2 + 1.5·x + 4s·exp(−(x − 5.5)²/0.8): a bump centred at 5.5, inside the gap.', ERR], see: 'Two clusters of points with nothing between them; the fitted line passes straight across the gap, missing the bump completely, and the confidence band is even narrow there.', real: 'A sensor that was off for a while.', why: 'The model is confident where it has no data. Interpolating across a gap is still a guess.' },
    rextrap: { one: 'Train on x below 6, test on x above 6, where the truth starts to bend.', how: [BASE1, 'True mean: 2 + 1.5·x + 0.35s·max(0, x − 6)²: straight up to 6, bending upward after.', 'The rows with x > 6 (at full strength) are the test set; the rest are training.'], see: 'The training points look perfectly linear; the hollow test points rise above the line; test error jumps.', real: 'A demand model trained on normal years and used in a boom.', why: 'A line is only validated where there were data.' },
    /* ---------------- Irrelevant features ---------------- */
    irnone: { one: 'Only features that matter.', how: [BASE1, 'y = 2 + 1.5·x + ε.'], see: 'R² and adjusted R² agree.', real: '—', why: 'The reference.' },
    irfew: { one: 'Three columns of pure noise are added.', how: [BASE1, 'Add n₁, n₂, n₃, each 10·u, independent of everything.', 'y = 2 + 1.5·x + ε: the n columns are not used.'], see: 'Their coefficients are near 0 with wide intervals; R² rises a little, adjusted R² does not.', real: 'Fields added "just in case".', why: 'R² never falls when you add a column, so judge with adjusted R² or a test set.' },
    irmany: { one: 'Eight columns of pure noise are added.', how: [BASE1, 'Add n₁ … n₈, each 10·u, independent of y.', 'y = 2 + 1.5·x + ε.'], see: 'Training error falls, test error rises, and some noise columns can look significant by chance.', real: 'Wide datasets with many weak candidate features.', why: 'With many columns, multiple testing produces false discoveries. Use lasso or cross-validated selection.' },
    ircopy: { one: 'The same information appears twice.', how: [BASE1, 'Add x_copy = x + (0.05 + 2(1 − s))·z: almost an exact copy at full strength.', 'y = 2 + 1.5·x + ε.'], see: 'x and x_copy share the credit arbitrarily (their slopes add up to about 1.5) and both SEs inflate.', real: 'Height in cm and in inches.', why: 'Keep one copy.' },
    /* ---------------- Missing data ---------------- */
    mnone: { one: 'Every y is recorded.', how: [BASE1, 'y = 2 + 1.5·x + ε.'], see: 'No hollow points.', real: '—', why: 'The reference.' },
    mcar: { one: 'Each y is lost by pure chance (missing completely at random).', how: [BASE1, 'y = 2 + 1.5·x + ε.', 'Each y is deleted with probability 0.3·s, whatever its x or y.', 'Rows without y are dropped (complete-case analysis).'], see: 'Hollow points scattered evenly; the line on the kept rows matches the line on all rows.', real: 'Lost forms, random server errors.', why: 'MCAR costs precision (fewer rows), not bias.' },
    mar: { one: 'y is lost more often when x is high (missing at random: the cause is an observed column).', how: [BASE1, 'y = 2 + 1.5·x + ε.', 'Each y is deleted with probability 0.7·s·(x/10)²: rarely at low x, often at high x.', 'Incomplete rows are dropped.'], see: 'Hollow points mostly at the right; the slope on the kept rows is still about right.', real: 'Older customers skipping an online question.', why: 'Dropping rows is fine for the regression when the cause of missingness is one of the features.' },
    mnar: { one: 'y is lost more often when y itself is high (missing not at random).', how: [BASE1, 'y = 2 + 1.5·x + ε.', 'Each y is deleted with probability 0.85·s / (1 + e^(−2.2·z_y)), where z_y is the standardised y: high values are lost most.', 'Incomplete rows are dropped.'], see: 'Hollow points mostly at the top; the line on the kept rows is flatter than the line on all rows.', real: 'High earners leaving income blank.', why: 'MNAR biases the estimate and the kept data alone cannot reveal it.' },
    /* ---------------- Target type ---------------- */
    tcont: { one: 'A continuous, unbounded y with bell-shaped noise.', how: [BASE1, 'y = 2 + 1.5·x + ε.'], see: 'The usual band around the line.', real: '—', why: 'The reference.' },
    tskew: { one: 'y grows by a fixed percentage per unit of x, with percentage noise.', how: [BASE1, 'Exponential version: e^(0.6 + 0.25x + 0.12·max(σ, 0.3)·z): each unit of x multiplies y by e^0.25 ≈ 1.28.', 'y = (1 − s)·(the straight-line version) + s·(the exponential version).'], see: 'A curve bending upward and fanning out; skewed residuals.', real: 'Prices, incomes, file sizes.', why: 'log(y) turns the curve into a line and the funnel into a band.' },
    tbound: { one: 'y is a score between 0 and 20 that follows an S-curve.', how: [BASE1, 'y = 20 / (1 + e^(−(−3 + 0.6x + 0.25·max(σ, 0.3)·z))).'], see: 'Points flatten near 0 and 20; the straight line predicts beyond both bounds.', real: 'Exam marks, percentages, ratings.', why: 'A straight line does not know about the bounds: use a logistic-type model or a logit transform.' },
    tcount: { one: 'y counts events: whole numbers whose spread grows with their mean.', how: [BASE1, 'Mean λ = e^(0.3 + 0.25x).', 'y = a Poisson draw with mean λ: 0, 1, 2, …'], see: 'Points in horizontal rows (whole numbers), spreading out as x grows.', real: 'Visits per day, claims per policy.', why: 'Poisson regression models log(mean) as a line, so predictions stay positive and the spread follows the mean.' },
    /* ---------------- Categorical ---------------- */
    cnone: { one: 'Only the numeric x.', how: [BASE1, 'y = 2 + 1.5·x + ε.'], see: 'One line describes every row.', real: '—', why: 'The reference.' },
    cbin: { one: 'A text column, segment (basic or premium), shifts y up for premium customers.', how: ['x = 10·u.', 'Each row gets a segment, basic or premium, recorded as text.', 'y = 2 + 1.5·x + 4s·[premium] + ε.', 'Step 5 encodes segment into one 0/1 column, segment_premium (basic is the reference).'], see: 'Two parallel clouds 4 units apart; two parallel fitted lines.', real: 'Free vs paid plan; weekday vs weekend.', why: 'The coefficient of segment_premium is the gap between premium and basic at the same x.' },
    cmulti: { one: 'A text column, region, with four levels, each with its own shift.', how: ['x = 10·u.', 'Each row gets a region: East, North, South or West (text).', 'y = 2 + 1.5·x + (0, +3s, −2s, +5s for East, North, South, West) + ε.', 'Step 5 makes three 0/1 columns, region_North, region_South, region_West; East is the reference.'], see: 'Four parallel clouds; one fitted line per region.', real: 'Sales by region; price by product type.', why: 'k levels need k − 1 dummies; each coefficient is a level’s gap from the reference; test the whole category with a partial F-test.' },
    chigh: { one: 'A text column, branch, with 25 levels and only a few rows per level.', how: ['x = 10·u.', 'Each row gets a branch B01 … B25 (every branch appears at least twice in training).', 'Each branch has its own random shift (sd 3s): y = 2 + 1.5·x + shift + ε.', 'Step 5 makes 24 0/1 columns, branch_B02 … branch_B25.'], see: 'A rainbow of points; 24 extra coefficients, most with huge SEs; test error well above training error.', real: 'Store ID, zip code, product SKU.', why: 'One-hot encoding a high-cardinality column overfits. Merge rare levels, use target encoding learned on training rows only, or a mixed model.' },
    /* ---------------- Hidden subgroups ---------------- */
    sgnone: { one: 'One population.', how: [BASE1, 'y = 2 + 1.5·x + ε.'], see: 'One cloud, one line.', real: '—', why: 'The reference.' },
    sgint: { one: 'The rows come from two groups (say, two stores) whose y differ by a fixed amount, but no group column was recorded.', how: ['Each row is given to group 0 or group 1 at random (about half each).', 'Group 0 gets x spread over 0–8; group 1 gets x between 3 and 10, so group 1 tends to have higher x.', 'Both groups have slope 1.5, but group 1 sits 7·s higher: y = 2 + 1.5x + 7s + ε for group 1, y = 2 + 1.5x + ε for group 0.', 'The group label is then thrown away: the model sees only x and y.'], see: 'Two parallel clouds (coloured here, although the model never sees the colours). The single fitted line runs between them and is steeper than 1.5, because the high group also has the high x, so the line mistakes "being in group 1" for "having more x". Residuals form two bands.', real: 'Sales from two stores, prices in two cities, scores from two schools.', why: 'An unrecorded group is an omitted variable: it biases the slope when it is related to x. Record the group and add it.' },
    sgslope: { one: 'Two groups where x has a different effect, and the group is not recorded.', how: ['Each row is in group 0 or 1 at random; x = 10·u for both.', 'Group 0: y = 2 + 1.5x + ε. Group 1: y = 2 + 1.5x − 2s·(x − 5) + ε, so its slope is 1.5 − 2s (−0.5 at full strength).', 'The group label is not given to the model.'], see: 'Two clouds that cross at x = 5 and spread apart on both sides; one pooled line with an in-between slope; residuals fan out.', real: 'A drug that works for one age group and not the other.', why: 'Different slopes need the group and the group × x interaction.' },
    simpson: { one: 'Within each group the slope is +1.5, but the pooled slope is negative (Simpson’s paradox).', how: ['Group 0 has x between 0 and 5; group 1 has x between 5 and 10.', 'Both groups have slope +1.5, but group 0 sits 18·s higher: y = 2 + 1.5x + 18s + ε for group 0.', 'The model sees x and y only.'], see: 'Two rising clouds, the left one high and the right one low; the pooled line slopes down through them.', real: 'Admission rates by department; treatment effects by severity.', why: 'Aggregating groups can reverse a relationship. Include the group, and think about which comparison answers your question.' },
    /* ---------------- Distribution shift ---------------- */
    shnone: { one: 'Test rows come from the same place as training rows.', how: [BASE1, 'y = 2 + 1.5·x + ε; a random 20% are the test rows.'], see: 'Test points mixed among training points.', real: '—', why: 'The reference.' },
    shfeat: { one: 'The inputs move but the rule stays (covariate shift).', how: ['Training rows: x = 10·u.', 'The last 20% of rows are the test set, and their x comes from around 7.5 (7.5 + 1.2z at full strength).', 'Every row: y = 2 + 1.5·x + ε.'], see: 'Hollow test points bunched at the right, still on the line; test error barely changes.', real: 'A model built in one region and used in another.', why: 'Covariate shift hurts only where the model is wrong; a correct model still predicts well.' },
    shrel: { one: 'The rule linking x to y changes in the test period (concept drift).', how: ['x = 10·u for every row.', 'The first 80% (training): y = 2 + 1.5·x + ε.', 'The last 20% (test): y = 2 + (1.5 − 1.2s)·x + 3s + ε: a much flatter slope.'], see: 'Hollow test points drift off the line, below it at high x; test residuals trend with x; test error jumps.', real: 'Customer behaviour after a policy change.', why: 'More old data cannot fix drift: monitor errors over time and retrain on recent data.' },
    /* ---------------- Leakage ---------------- */
    lknone: { one: 'Every feature is known before y, and the split comes first.', how: [BASE1, 'y = 2 + 1.5·x + ε.'], see: 'Honest test scores.', real: '—', why: 'The reference.' },
    lktarget: { one: 'A feature is built from y: it exists in the historical data, but not at prediction time.', how: [BASE1, 'y = 2 + 1.5·x + ε.', 'Add a column leak = y + (0.3 + 4(1 − s))·z: almost y itself at full strength.'], see: 'Nothing odd in y vs x. The leak column predicts y almost perfectly, so train and test scores are excellent; without it (as in real use) the error is worse than an honest model.', real: '"Total paid" predicting "will default"; a diagnosis code predicting the disease.', why: 'Ask of every column: is it known before the outcome? If a feature looks too good to be true, it usually is.' },
    lkprep: { one: 'A preprocessing step that learns from y (target encoding) used every row, test rows included, before the split.', how: [BASE1, 'y = 2 + 1.5·x + ε.', 'Give each row an ID-like level (about one row per level) that has no effect on y.', 'Replace each level by the mean y of its rows, computed on ALL rows (column enc). For a level seen once, enc is the row’s own y.', 'Only then split into train and test.'], see: 'Test error better than the baseline, which is impossible for a useless column; the honest version (encoding learned on training rows) is worse.', real: 'Target encoding, feature selection or imputation fitted on the full dataset.', why: 'Every step that learns from data must learn from the training rows only: put it inside a pipeline, after the split.' }
  };
  function html(a, v, isBase, cur, open){
    const x = A[v.id]; if (!x) return '';
    return `<details class="about" id="aboutD"${open ? ' open' : ''}><summary>About this variant: ${esc(v.name)}${isBase ? ' (baseline)' : ''}</summary><div class="about-b">
      <p class="about-one"><b>In one sentence.</b> ${x.one}</p>
      <div class="about-g"><div><h4>How the data are made</h4><ol>${x.how.map(s => `<li>${s}</li>`).join('')}</ol></div>
      <div><h4>What you will see</h4><p>${x.see}</p><h4>Where it happens in real data</h4><p>${x.real}</p><h4>Why it matters in an interview</h4><p>${x.why}</p></div></div></div></details>`;
  }
  return { html, has: id => !!A[id] };
})();
